local KTool = CS.Engine.Lib.KTool
---@class OverseaManagePersonnelChargeConsumeCell
local OverseaManagePersonnelChargeConsumeCell = Class('OverseaManagePersonnelChargeConsumeCell')
local EasyTouch =  CS.HedgehogTeam.EasyTouch.EasyTouch
local QuickLongTapType = typeof(CS.HedgehogTeam.EasyTouch.QuickLongTap)
local cs_coroutine      = require 'XLua.cs_coroutine'
local Yielders = CS.Engine.Lib.Yielders

function OverseaManagePersonnelChargeConsumeCell:__init()
    self.callBack = nil
    self.curNum = 0
    self.haveNum = nil
    self.goodsId = nil
    self.isCanTip = true
end

function OverseaManagePersonnelChargeConsumeCell:__delete()
    self.callBack = nil
    self.curNum = nil
    self.haveNum = nil
    self.goodsId = nil
    self.isCanTip = nil
    EasyTouch.instance.enableUIMode = false
    EasyTouch.SetUICompatibily( true)
end

function OverseaManagePersonnelChargeConsumeCell:SetCallBack(callBack,limitCallBack)
    self.callBack = callBack
    self.limitCallBack = limitCallBack
end

function OverseaManagePersonnelChargeConsumeCell:Awake()
    self:AddUIClick()
end

function OverseaManagePersonnelChargeConsumeCell:InitShow()
    self.curNum = 0
    KTool.SetActive(self.ChooseQuantityNode.gameObject,false)
end

function OverseaManagePersonnelChargeConsumeCell:AddUIClick()
    SetButtonAction(self.BtnReduce,Bind(self,self.OnBtnReduceClick))
    SetButtonAction(self.BtnImgGoods,Bind(self,self.OnBtnGoodsClick))

    self.longAddTapComp = KTool.GetOrAddComponent(self.BtnImgGoods.gameObject, QuickLongTapType)
    self.longAddTapComp.actionTriggering = 1
    self.longAddTapComp.onLongTap:AddListener(Bind(self, self.OnBtnGoodsClick))

    self.longReduceTapComp = KTool.GetOrAddComponent(self.BtnReduce.gameObject, QuickLongTapType)
    self.longReduceTapComp.actionTriggering = 1
    self.longReduceTapComp.onLongTap:AddListener(Bind(self, self.OnBtnReduceClick))

end

function OverseaManagePersonnelChargeConsumeCell:RefreshShow(id)
    self:InitShow()
    self.goodsId = id
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.goodsId)
    if goodsVo then
        CfUtils.FillImage(self.ImgGoodsIcon,goodsVo.photoPath)
        CfUtils.FillImage(self.ImgQuality, GoodsUtils.GetFishBgByQualityType(goodsVo.quality))
    end
    self.haveNum = GoodsUtils.GetThingNo(self.goodsId)
    CfUtils.FillText(self.TextNumber,"x"..self.haveNum)
end

function OverseaManagePersonnelChargeConsumeCell:OnBtnReduceClick()
    self.curNum = self.curNum - 1
    if self.curNum < 1 then
        self.curNum = 1
    end
    CfUtils.FillText(self.CostNumber,self.curNum)
    if self.callBack then
        self.callBack(self.goodsId,self.curNum)
    end
end

function OverseaManagePersonnelChargeConsumeCell:OnBtnGoodsClick()
    local haveNum = GoodsUtils.GetThingNo(self.goodsId)
    if haveNum > 0 then
        local isOver = false
        if self.limitCallBack then
            isOver = self.limitCallBack()
        end
        if isOver  then
            if self.isCanTip then
                self.isCanTip = false
                GameUtils.Toast(localize("当前电量已达上限"))
                cs_coroutine.start(function()
                        coroutine.yield(Yielders.GetWaitForSeconds(3))
                        self.isCanTip = true
                        self.showTipCo = nil
                    end)
            end
            return
        end
        self.curNum = self.curNum + 1
        KTool.SetActive(self.ChooseQuantityNode.gameObject,true)
        if self.curNum > haveNum then
            self.curNum = haveNum
        end
        CfUtils.FillText(self.CostNumber,self.curNum)
        if self.callBack then
            self.callBack(self.goodsId,self.curNum)
        end
    else
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.goodsId)
        if goodsVo then
            GameUtils.ShowCommonGoodsTipsBoard(self.BtnImgGoods.transform.parent.gameObject, goodsVo.id, true)
        end
    end
end

function OverseaManagePersonnelChargeConsumeCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManagePersonnelChargeConsumeCell